if.script:
// the printed card (design §18 Print documents), every value escaped
const L = (text) => ec.l10n.localize(text)
const enc = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const rec = ec.service.sync().name('ironstone.commons.ContactServices.get#ContactRecord').parameters({partyId: partyId}).call() || {}
if (!rec.found) { printHtml = '<p>' + enc(L('This contact is not available')) + '</p>'; return }
const record = rec.record
const row = (label, value) => value ? '<tr><td class="field-title">' + enc(L(label)) + '</td><td class="field-value">' + value + '</td></tr>' : ''
const lines = (text) => enc(text).replace(/\n/g, '<br>')
const current = (list) => Array.from(list || []).filter((item) => !item.expired)
const mechs = current(rec.contactMechList).map((mech) => enc(mech.value) + ' <span style="color:#555">(' + enc([mech.typeLabel, mech.purposeText]
        .filter((part) => part).join(' · ')) + ')</span>').join('<br>')
const addresses = current(rec.addressList).map((address) => lines(address.text) + (address.purposeText ? ' <span style="color:#555">('
        + enc(address.purposeText) + ')</span>' : '')).join('<br><br>')
const organizations = Array.from(rec.organizationList || []).map((org) => enc([org.organizationName, org.jobTitle]
        .filter((part) => part).join(' · '))).join('<br>')
const books = Array.from(rec.bookList || []).map((book) => enc(book.contactBookName + (book.memberGroupText ? ' · ' + book.memberGroupText : ''))).join('<br>')
const notes = Array.from(rec.noteList || []).map((note) => '<p>' + lines(note.noteText) + '<br><span style="color:#555">'
        + enc([note.userName, note.noteDateText].filter((part) => part).join(' · ')) + '</span></p>').join('')
printHtml = '<div class="box-header">' + enc(record.name) + '</div><p style="color:#555">' + enc([record.kindLabel, record.pseudoId].filter((part) => part).join(' · '))
    + '</p><table class="field">' + row('Organization', organizations) + row('Contact info', mechs) + row('Addresses', addresses)
    + row('Birthday', enc(record.birthDate)) + row('About', record.comments ? lines(record.comments) : '') + row('Books and groups', books)
    + '</table>' + (notes ? '<div class="group-title" style="margin-top:8pt">' + enc(L('Notes')) + '</div>' + notes : '')
